/**
 * 姿态分析引擎
 * 核心算法模块，用于分析传感器数据并判断姿态状态
 */

import { POSTURE } from '@vela-quickapps/shared/utils/constants'

class PostureAnalyzer {
  constructor() {
    // 姿态状态
    this.currentPosture = POSTURE.TYPES.UNKNOWN
    this.currentStatus = POSTURE.STATUS.GOOD

    // 角度数据
    this.neckAngle = 0
    this.backAngle = 0
    this.shoulderAngle = 0

    // 历史数据（用于平滑处理）
    this.angleHistory = []
    this.maxHistoryLength = 10

    // 阈值配置
    this.thresholds = {
      neckLow: POSTURE.ANGLES.NECK_LOW_THRESHOLD,
      backCurve: POSTURE.ANGLES.BACK_CURVE_THRESHOLD,
      sittingMin: POSTURE.ANGLES.SITTING_ANGLE_MIN,
      sittingMax: POSTURE.ANGLES.SITTING_ANGLE_MAX,
      standingMin: POSTURE.ANGLES.STANDING_ANGLE_MIN,
      standingMax: POSTURE.ANGLES.STANDING_ANGLE_MAX
    }
  }

  /**
   * 分析传感器数据
   * @param {Object} accelerometerData - 加速度计数据 {x, y, z}
   * @param {Object} gyroscopeData - 陀螺仪数据 {x, y, z} (可选)
   * @returns {Object} 分析结果
   */
  analyze(accelerometerData, gyroscopeData = null) {
    const { x, y, z } = accelerometerData

    // 计算各部位角度
    this.neckAngle = this.calculateNeckAngle(x, y, z)
    this.backAngle = this.calculateBackAngle(x, y, z)
    this.shoulderAngle = this.calculateShoulderAngle(x, y, z)

    // 添加到历史记录
    this.addToHistory({
      neck: this.neckAngle,
      back: this.backAngle,
      shoulder: this.shoulderAngle,
      timestamp: Date.now()
    })

    // 使用平滑后的角度
    const smoothedAngles = this.getSmoothedAngles()

    // 判断姿态类型
    this.currentPosture = this.determinePostureType(z)

    // 判断姿态状态
    this.currentStatus = this.determinePostureStatus(smoothedAngles)

    return {
      posture: this.currentPosture,
      status: this.currentStatus,
      angles: {
        neck: smoothedAngles.neck,
        back: smoothedAngles.back,
        shoulder: smoothedAngles.shoulder
      },
      rawAngles: {
        neck: this.neckAngle,
        back: this.backAngle,
        shoulder: this.shoulderAngle
      },
      timestamp: Date.now()
    }
  }

  /**
   * 计算颈部角度
   * 基于加速度计数据估算头部倾斜角度
   */
  calculateNeckAngle(x, y, z) {
    // 使用反正切计算角度
    // x轴主要反映左右倾斜，z轴反映前后倾斜
    const radian = Math.atan2(Math.abs(x), Math.sqrt(y * y + z * z))
    const angle = Math.round(radian * (180 / Math.PI))
    return Math.min(Math.max(angle, 0), 90)
  }

  /**
   * 计算背部角度
   * 基于加速度计数据估算背部弯曲角度
   */
  calculateBackAngle(x, y, z) {
    // y轴主要反映背部弯曲
    const radian = Math.atan2(Math.abs(y), Math.sqrt(x * x + z * z))
    const angle = Math.round(radian * (180 / Math.PI))
    return Math.min(Math.max(angle, 0), 90)
  }

  /**
   * 计算肩部角度
   * 基于加速度计数据估算肩部倾斜角度
   */
  calculateShoulderAngle(x, y, z) {
    // 综合考虑x和y轴
    const radian = Math.atan2(Math.abs(x + y), z)
    const angle = Math.round(radian * (180 / Math.PI))
    return Math.min(Math.max(angle, 0), 90)
  }

  /**
   * 判断姿态类型
   * @param {number} z - Z轴加速度
   * @returns {string} 姿态类型
   */
  determinePostureType(z) {
    // 根据z轴判断姿态
    // 站立时z轴接近重力加速度
    // 坐着时z轴较小
    // 躺着时z轴接近0或负值
    if (z > 8) return POSTURE.TYPES.STANDING
    if (z < -2) return POSTURE.TYPES.LYING
    return POSTURE.TYPES.SITTING
  }

  /**
   * 判断姿态状态
   * @param {Object} angles - 平滑后的角度
   * @returns {string} 姿态状态
   */
  determinePostureStatus(angles) {
    // 检查是否姿态不佳
    if (angles.neck > this.thresholds.neckLow ||
        angles.back > this.thresholds.backCurve) {
      return POSTURE.STATUS.POOR
    }

    // 检查是否姿态一般
    if (angles.neck > this.thresholds.neckLow * 0.7 ||
        angles.back > this.thresholds.backCurve * 0.7) {
      return POSTURE.STATUS.FAIR
    }

    return POSTURE.STATUS.GOOD
  }

  /**
   * 添加数据到历史记录
   */
  addToHistory(data) {
    this.angleHistory.push(data)
    if (this.angleHistory.length > this.maxHistoryLength) {
      this.angleHistory.shift()
    }
  }

  /**
   * 获取平滑后的角度（移动平均）
   */
  getSmoothedAngles() {
    if (this.angleHistory.length === 0) {
      return { neck: 0, back: 0, shoulder: 0 }
    }

    const sum = this.angleHistory.reduce((acc, item) => ({
      neck: acc.neck + item.neck,
      back: acc.back + item.back,
      shoulder: acc.shoulder + item.shoulder
    }), { neck: 0, back: 0, shoulder: 0 })

    const count = this.angleHistory.length

    return {
      neck: Math.round(sum.neck / count),
      back: Math.round(sum.back / count),
      shoulder: Math.round(sum.shoulder / count)
    }
  }

  /**
   * 重置分析器
   */
  reset() {
    this.currentPosture = POSTURE.TYPES.UNKNOWN
    this.currentStatus = POSTURE.STATUS.GOOD
    this.neckAngle = 0
    this.backAngle = 0
    this.shoulderAngle = 0
    this.angleHistory = []
  }

  /**
   * 更新阈值配置
   * @param {Object} newThresholds - 新的阈值配置
   */
  updateThresholds(newThresholds) {
    this.thresholds = {
      ...this.thresholds,
      ...newThresholds
    }
  }

  /**
   * 获取当前配置
   */
  getConfig() {
    return {
      thresholds: { ...this.thresholds },
      maxHistoryLength: this.maxHistoryLength
    }
  }
}

export default new PostureAnalyzer()

/**
 * 角度计算模块
 * 提供精确的角度计算和转换功能
 */

class AngleCalculator {
  constructor() {
    // 重力加速度常量 (m/s²)
    this.GRAVITY = 9.81

    // 角度转换系数
    this.RAD_TO_DEG = 180 / Math.PI
    this.DEG_TO_RAD = Math.PI / 180
  }

  /**
   * 计算向量角度
   * @param {Object} vector - 向量 {x, y, z}
   * @param {string} axis - 参考轴 ('x', 'y', 'z')
   * @returns {number} 角度（度）
   */
  vectorAngle(vector, axis = 'z') {
    const { x, y, z } = vector

    switch (axis) {
      case 'x':
        return Math.atan2(x, Math.sqrt(y * y + z * z)) * this.RAD_TO_DEG
      case 'y':
        return Math.atan2(y, Math.sqrt(x * x + z * z)) * this.RAD_TO_DEG
      case 'z':
        return Math.atan2(z, Math.sqrt(x * x + y * y)) * this.RAD_TO_DEG
      default:
        return 0
    }
  }

  /**
   * 计算两个向量之间的夹角
   * @param {Object} v1 - 向量1 {x, y, z}
   * @param {Object} v2 - 向量2 {x, y, z}
   * @returns {number} 角度（度）
   */
  angleBetweenVectors(v1, v2) {
    const dotProduct = v1.x * v2.x + v1.y * v2.y + v1.z * v2.z
    const magnitude1 = this.vectorMagnitude(v1)
    const magnitude2 = this.vectorMagnitude(v2)

    if (magnitude1 === 0 || magnitude2 === 0) return 0

    const cosAngle = dotProduct / (magnitude1 * magnitude2)
    // 限制cos值在有效范围内
    const clampedCos = Math.max(-1, Math.min(1, cosAngle))
    return Math.acos(clampedCos) * this.RAD_TO_DEG
  }

  /**
   * 计算向量的模
   * @param {Object} vector - 向量 {x, y, z}
   * @returns {number} 模
   */
  vectorMagnitude(vector) {
    return Math.sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z)
  }

  /**
   * 归一化向量
   * @param {Object} vector - 向量 {x, y, z}
   * @returns {Object} 归一化后的向量
   */
  normalizeVector(vector) {
    const mag = this.vectorMagnitude(vector)
    if (mag === 0) return { x: 0, y: 0, z: 0 }

    return {
      x: vector.x / mag,
      y: vector.y / mag,
      z: vector.z / mag
    }
  }

  /**
   * 计算俯仰角 (Pitch)
   * 绕X轴旋转的角度
   * @param {Object} accelerometer - 加速度计数据
   * @returns {number} 俯仰角（度）
   */
  pitch(accelerometer) {
    const { x, y, z } = accelerometer
    return Math.atan2(-x, Math.sqrt(y * y + z * z)) * this.RAD_TO_DEG
  }

  /**
   * 计算横滚角 (Roll)
   * 绕Y轴旋转的角度
   * @param {Object} accelerometer - 加速度计数据
   * @returns {number} 横滚角（度）
   */
  roll(accelerometer) {
    const { x, y, z } = accelerometer
    return Math.atan2(y, Math.sqrt(x * x + z * z)) * this.RAD_TO_DEG
  }

  /**
   * 计算偏航角 (Yaw)
   * 绕Z轴旋转的角度（需要磁力计数据）
   * @param {Object} magnetometer - 磁力计数据
   * @returns {number} 偏航角（度）
   */
  yaw(magnetometer) {
    const { x, y } = magnetometer
    return Math.atan2(y, x) * this.RAD_TO_DEG
  }

  /**
   * 计算姿态四元数
   * @param {Object} accelerometer - 加速度计数据
   * @param {Object} gyroscope - 陀螺仪数据
   * @returns {Object} 四元数 {w, x, y, z}
   */
  quaternionFromAcceleration(accelerometer, gyroscope = null) {
    const norm = this.normalizeVector(accelerometer)

    // 简化的姿态估计
    const pitch = Math.asin(-norm.x) * this.RAD_TO_DEG
    const roll = Math.atan2(norm.y, norm.z) * this.RAD_TO_DEG

    // 转换为四元数
    const cy = Math.cos(roll * 0.5 * this.DEG_TO_RAD)
    const sy = Math.sin(roll * 0.5 * this.DEG_TO_RAD)
    const cp = Math.cos(pitch * 0.5 * this.DEG_TO_RAD)
    const sp = Math.sin(pitch * 0.5 * this.DEG_TO_RAD)

    return {
      w: cy * cp,
      x: sy * cp,
      y: cy * sp,
      z: sy * sp
    }
  }

  /**
   * 角度平滑滤波
   * @param {number} currentAngle - 当前角度
   * @param {number} previousAngle - 上一次角度
   * @param {number} alpha - 滤波系数 (0-1，越大越跟隨当前值)
   * @returns {number} 平滑后的角度
   */
  smoothAngle(currentAngle, previousAngle, alpha = 0.3) {
    return previousAngle + alpha * (currentAngle - previousAngle)
  }

  /**
   * 角度限幅
   * @param {number} angle - 角度
   * @param {number} min - 最小值
   * @param {number} max - 最大值
   * @returns {number} 限幅后的角度
   */
  clampAngle(angle, min, max) {
    return Math.max(min, Math.min(max, angle))
  }

  /**
   * 角度差计算（考虑360°循环）
   * @param {number} angle1 - 角度1
   * @param {number} angle2 - 角度2
   * @returns {number} 角度差
   */
  angleDifference(angle1, angle2) {
    let diff = angle2 - angle1
    while (diff > 180) diff -= 360
    while (diff < -180) diff += 360
    return diff
  }

  /**
   * 判断角度是否在范围内
   * @param {number} angle - 角度
   * @param {number} min - 最小值
   * @param {number} max - 最大值
   * @returns {boolean} 是否在范围内
   */
  isAngleInRange(angle, min, max) {
    return angle >= min && angle <= max
  }

  /**
   * 将角度转换为弧度
   * @param {number} degrees - 角度
   * @returns {number} 弧度
   */
  toRadians(degrees) {
    return degrees * this.DEG_TO_RAD
  }

  /**
   * 将弧度转换为角度
   * @param {number} radians - 弧度
   * @returns {number} 角度
   */
  toDegrees(radians) {
    return radians * this.RAD_TO_DEG
  }
}

export default new AngleCalculator()

/**
 * 警报管理器
 * 负责姿态异常检测和提醒管理
 */

import eventBus, { EVENTS } from '@vela-quickapps/shared/services/event-bus'
import { POSTURE } from '@vela-quickapps/shared/utils/constants'

class AlertManager {
  constructor() {
    // 警报状态
    this.isEnabled = true
    this.lastAlertTime = 0
    this.todayAlertCount = 0

    // 配置
    this.config = {
      idleTimeout: POSTURE.ALERT.IDLE_TIMEOUT,  // 久坐提醒时间
      maxAlertsPerDay: POSTURE.ALERT.MAX_ALERTS_PER_DAY,
      cooldown: POSTURE.ALERT.COOLDOWN  // 提醒冷却时间
    }

    // 久坐计时器
    this.idleTimer = null
    this.idleStartTime = null

    // 姿态状态追踪
    this.badPostureStartTime = null
    this.badPostureThreshold = 5000  // 持续不良姿态5秒触发提醒
  }

  /**
   * 检查姿态并触发提醒
   * @param {Object} postureData - 姿态数据
   */
  checkPosture(postureData) {
    if (!this.isEnabled) return

    const { status, posture } = postureData
    const now = Date.now()

    // 检查冷却时间
    if (now - this.lastAlertTime < this.config.cooldown) {
      return
    }

    // 检查每日提醒上限
    if (this.todayAlertCount >= this.config.maxAlertsPerDay) {
      return
    }

    // 检查不良姿态
    if (status === POSTURE.STATUS.POOR) {
      if (!this.badPostureStartTime) {
        this.badPostureStartTime = now
      } else if (now - this.badPostureStartTime >= this.badPostureThreshold) {
        this.triggerAlert('bad_posture', posture)
        this.badPostureStartTime = null
      }
    } else {
      this.badPostureStartTime = null
    }
  }

  /**
   * 启动久坐提醒
   */
  startIdleTimer() {
    if (this.idleTimer) {
      clearInterval(this.idleTimer)
    }

    this.idleStartTime = Date.now()

    this.idleTimer = setInterval(() => {
      const now = Date.now()
      if (now - this.idleStartTime >= this.config.idleTimeout) {
        this.triggerAlert('idle', { duration: Math.floor((now - this.idleStartTime) / 60000) })
        this.idleStartTime = now  // 重置计时
      }
    }, 60000)  // 每分钟检查一次
  }

  /**
   * 停止久坐提醒
   */
  stopIdleTimer() {
    if (this.idleTimer) {
      clearInterval(this.idleTimer)
      this.idleTimer = null
    }
    this.idleStartTime = null
  }

  /**
   * 触发警报
   * @param {string} type - 警报类型
   * @param {Object} data - 相关数据
   */
  triggerAlert(type, data = {}) {
    const now = Date.now()
    this.lastAlertTime = now
    this.todayAlertCount++

    const alertData = {
      type,
      timestamp: now,
      message: this.getAlertMessage(type, data),
      ...data
    }

    // 发布警报事件
    eventBus.publish(EVENTS.POSTURE_ALERT, alertData)

    // 触发振动提醒
    this.vibrate()

    console.log('[AlertManager] 触发警报:', alertData)
  }

  /**
   * 获取警报消息
   * @param {string} type - 警报类型
   * @param {Object} data - 相关数据
   * @returns {string} 警报消息
   */
  getAlertMessage(type, data) {
    switch (type) {
      case 'bad_posture':
        return '请注意保持正确坐姿'
      case 'idle':
        return `您已久坐${data.duration || 30}分钟，请起身活动`
      case 'neck_low':
        return '请抬起头，保持视线水平'
      case 'back_curve':
        return '请挺直腰背，保持正确坐姿'
      default:
        return '请注意姿势'
    }
  }

  /**
   * 触发振动
   */
  vibrate() {
    try {
      // 使用 OpenVela 振动 API
      const vibrator = require('@system.vibrator')
      vibrator.vibrate({
        mode: 'short',
        success: () => {
          console.log('[AlertManager] 振动成功')
        },
        fail: (data, code) => {
          console.error('[AlertManager] 振动失败', code)
        }
      })
    } catch (e) {
      console.log('[AlertManager] 振动不可用')
    }
  }

  /**
   * 启用/禁用提醒
   * @param {boolean} enabled - 是否启用
   */
  setEnabled(enabled) {
    this.isEnabled = enabled
    if (!enabled) {
      this.stopIdleTimer()
    }
  }

  /**
   * 更新配置
   * @param {Object} newConfig - 新配置
   */
  updateConfig(newConfig) {
    this.config = {
      ...this.config,
      ...newConfig
    }
  }

  /**
   * 重置今日提醒计数
   */
  resetDailyCount() {
    this.todayAlertCount = 0
  }

  /**
   * 获取今日提醒统计
   * @returns {Object} 统计数据
   */
  getTodayStats() {
    return {
      count: this.todayAlertCount,
      maxCount: this.config.maxAlertsPerDay,
      remaining: this.config.maxAlertsPerDay - this.todayAlertCount
    }
  }

  /**
   * 清理资源
   */
  cleanup() {
    this.stopIdleTimer()
    this.badPostureStartTime = null
  }
}

export default new AlertManager()

/**
 * 数据采集器
 * 负责从传感器采集数据并进行预处理
 */

import sensorService from '@vela-quickapps/shared/services/sensor-service'
import eventBus, { EVENTS } from '@vela-quickapps/shared/services/event-bus'
import postureAnalyzer from './posture-analyzer'
import alertManager from './alert-manager'

class DataCollector {
  constructor() {
    // 采集状态
    this.isCollecting = false
    this.collectInterval = null
    this.collectFrequency = 100  // 采集频率（毫秒）

    // 数据缓冲区
    this.dataBuffer = []
    this.maxBufferSize = 100

    // 统计信息
    this.stats = {
      totalSamples: 0,
      dropSamples: 0,
      startTime: null
    }

    // 回调函数
    this.onDataCallback = null
    this.onPostureChangeCallback = null
  }

  /**
   * 开始数据采集
   * @param {Object} options - 采集选项
   */
  start(options = {}) {
    if (this.isCollecting) {
      console.warn('[DataCollector] 已经在采集中')
      return
    }

    const {
      frequency = 100,
      onData,
      onPostureChange
    } = options

    this.collectFrequency = frequency
    this.onDataCallback = onData
    this.onPostureChangeCallback = onPostureChange

    // 订阅传感器数据
    sensorService.subscribeAccelerometer((data) => {
      this.processSensorData(data)
    })

    // 启动定时采集
    this.collectInterval = setInterval(() => {
      this.collectData()
    }, this.collectFrequency)

    this.isCollecting = true
    this.stats.startTime = Date.now()

    // 启动久坐提醒
    alertManager.startIdleTimer()

    console.log('[DataCollector] 开始采集，频率:', this.collectFrequency, 'ms')
  }

  /**
   * 停止数据采集
   */
  stop() {
    if (!this.isCollecting) {
      return
    }

    // 取消传感器订阅
    sensorService.unsubscribeAccelerometer()

    // 停止定时采集
    if (this.collectInterval) {
      clearInterval(this.collectInterval)
      this.collectInterval = null
    }

    this.isCollecting = false

    // 停止久坐提醒
    alertManager.stopIdleTimer()

    console.log('[DataCollector] 停止采集，统计:', this.getStats())
  }

  /**
   * 处理传感器数据
   * @param {Object} data - 传感器数据
   */
  processSensorData(data) {
    this.stats.totalSamples++

    // 数据预处理
    const processedData = this.preprocessData(data)

    // 添加到缓冲区
    this.addToBuffer(processedData)

    // 姿态分析
    const analysisResult = postureAnalyzer.analyze(processedData)

    // 检查警报
    alertManager.checkPosture(analysisResult)

    // 触发回调
    if (this.onDataCallback) {
      this.onDataCallback({
        raw: data,
        processed: processedData,
        analysis: analysisResult
      })
    }

    // 检查姿态变化
    if (this.onPostureChangeCallback) {
      this.onPostureChangeCallback(analysisResult)
    }
  }

  /**
   * 数据预处理
   * @param {Object} data - 原始数据
   * @returns {Object} 处理后的数据
   */
  preprocessData(data) {
    // 1. 数据滤波（简单低通滤波）
    const filtered = this.lowPassFilter(data)

    // 2. 数据归一化
    const normalized = this.normalizeData(filtered)

    return {
      x: normalized.x,
      y: normalized.y,
      z: normalized.z,
      timestamp: data.timestamp || Date.now()
    }
  }

  /**
   * 低通滤波
   * @param {Object} data - 原始数据
   * @returns {Object} 滤波后的数据
   */
  lowPassFilter(data) {
    const alpha = 0.8  // 滤波系数

    // 获取上一次的数据
    const lastData = this.dataBuffer.length > 0
      ? this.dataBuffer[this.dataBuffer.length - 1]
      : data

    return {
      x: lastData.x + alpha * (data.x - lastData.x),
      y: lastData.y + alpha * (data.y - lastData.y),
      z: lastData.z + alpha * (data.z - lastData.z)
    }
  }

  /**
   * 数据归一化
   * @param {Object} data - 数据
   * @returns {Object} 归一化后的数据
   */
  normalizeData(data) {
    // 将加速度值归一化到 -1 到 1 范围
    const maxValue = 16  // 最大加速度值

    return {
      x: Math.max(-1, Math.min(1, data.x / maxValue)),
      y: Math.max(-1, Math.min(1, data.y / maxValue)),
      z: Math.max(-1, Math.min(1, data.z / maxValue))
    }
  }

  /**
   * 添加数据到缓冲区
   * @param {Object} data - 数据
   */
  addToBuffer(data) {
    this.dataBuffer.push(data)

    // 限制缓冲区大小
    if (this.dataBuffer.length > this.maxBufferSize) {
      this.dataBuffer.shift()
      this.stats.dropSamples++
    }
  }

  /**
   * 收集数据
   */
  collectData() {
    // 定时处理缓冲区数据
    if (this.dataBuffer.length > 0) {
      const batchData = this.dataBuffer.splice(0, 10)  // 每次处理10条

      // 发布数据批量处理事件
      eventBus.publish(EVENTS.SENSOR_DATA, {
        type: 'batch',
        data: batchData,
        timestamp: Date.now()
      })
    }
  }

  /**
   * 获取统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    const duration = this.stats.startTime
      ? Date.now() - this.stats.startTime
      : 0

    return {
      ...this.stats,
      duration,
      samplesPerSecond: duration > 0
        ? Math.round(this.stats.totalSamples / (duration / 1000))
        : 0,
      bufferSize: this.dataBuffer.length
    }
  }

  /**
   * 设置采集频率
   * @param {number} frequency - 频率（毫秒）
   */
  setFrequency(frequency) {
    this.collectFrequency = frequency

    if (this.isCollecting) {
      // 重启定时器
      if (this.collectInterval) {
        clearInterval(this.collectInterval)
      }
      this.collectInterval = setInterval(() => {
        this.collectData()
      }, this.collectFrequency)
    }
  }

  /**
   * 清空缓冲区
   */
  clearBuffer() {
    this.dataBuffer = []
    this.stats.dropSamples = 0
  }

  /**
   * 重置统计
   */
  resetStats() {
    this.stats = {
      totalSamples: 0,
      dropSamples: 0,
      startTime: Date.now()
    }
  }

  /**
   * 清理资源
   */
  cleanup() {
    this.stop()
    this.clearBuffer()
    this.resetStats()
    this.onDataCallback = null
    this.onPostureChangeCallback = null
  }
}

export default new DataCollector()

/**
 * 国际化服务
 */

import zhCN from './zh-CN.json'
import en from './en.json'

class I18n {
  constructor() {
    this.locale = 'zh-CN'
    this.messages = {
      'zh-CN': zhCN,
      'en': en
    }
  }

  /**
   * 设置语言
   * @param {string} locale - 语言代码
   */
  setLocale(locale) {
    if (this.messages[locale]) {
      this.locale = locale
    } else {
      console.warn(`[I18n] 不支持的语言: ${locale}`)
    }
  }

  /**
   * 获取当前语言
   * @returns {string} 语言代码
   */
  getLocale() {
    return this.locale
  }

  /**
   * 翻译文本
   * @param {string} key - 键名，如 'home.title'
   * @param {Object} params - 插值参数
   * @returns {string} 翻译后的文本
   */
  t(key, params = {}) {
    const keys = key.split('.')
    let value = this.messages[this.locale]

    for (const k of keys) {
      if (value && typeof value === 'object') {
        value = value[k]
      } else {
        value = undefined
        break
      }
    }

    if (value === undefined) {
      console.warn(`[I18n] 未找到翻译: ${key}`)
      return key
    }

    // 替换参数
    if (typeof value === 'string' && Object.keys(params).length > 0) {
      return value.replace(/\{(\w+)\}/g, (match, paramKey) => {
        return params[paramKey] !== undefined ? params[paramKey] : match
      })
    }

    return value
  }

  /**
   * 获取所有翻译
   * @param {string} namespace - 命名空间
   * @returns {Object} 翻译对象
   */
  getMessages(namespace) {
    const messages = this.messages[this.locale]
    if (namespace) {
      return messages[namespace] || {}
    }
    return messages
  }

  /**
   * 添加语言包
   * @param {string} locale - 语言代码
   * @param {Object} messages - 翻译内容
   */
  addLocale(locale, messages) {
    this.messages[locale] = {
      ...(this.messages[locale] || {}),
      ...messages
    }
  }

  /**
   * 检测系统语言
   * @returns {string} 语言代码
   */
  detectLocale() {
    // 尝试从系统获取语言设置
    try {
      const systemInfo = require('@system.device')
      const language = systemInfo.language || 'zh-CN'
      return language.startsWith('zh') ? 'zh-CN' : 'en'
    } catch (e) {
      return 'zh-CN'
    }
  }

  /**
   * 初始化（自动检测语言）
   */
  init() {
    this.locale = this.detectLocale()
    console.log(`[I18n] 初始化完成，当前语言: ${this.locale}`)
  }
}

export default new I18n()

