/**
 * 生成模拟姿态数据
 * @param {string} postureType - 姿态类型
 * @returns {Object} 姿态数据
 */
export function generatePostureData(postureType = 'sitting') {
  const baseAngles = {
    sitting: { neck: 10, back: 15 },
    standing: { neck: 5, back: 8 },
    lying: { neck: 25, back: 35 }
  }

  const base = baseAngles[postureType] || baseAngles.sitting
  const variance = 5

  return {
    neckAngle: base.neck + (Math.random() - 0.5) * variance,
    backAngle: base.back + (Math.random() - 0.5) * variance,
    postureType,
    status: getStatusFromAngles(base.neck, base.back),
    timestamp: Date.now()
  }
}

/**
 * 根据角度判断状态
 */
function getStatusFromAngles(neck, back) {
  if (neck > 20 || back > 30) return 'poor'
  if (neck > 15 || back > 20) return 'fair'
  return 'good'
}

