/**
 * 生成历史记录数据
 * @param {number} days - 天数
 * @returns {Array} 历史记录数组
 */
export function generateHistoryData(days = 7) {
  const data = []
  const now = Date.now()

  for (let i = 0; i < days; i++) {
    const dayTimestamp = now - i * 24 * 60 * 60 * 1000
    const recordsPerDay = Math.floor(5 + Math.random() * 10)

    for (let j = 0; j < recordsPerDay; j++) {
      const posture = generatePostureData()
      data.push({
        ...posture,
        timestamp: dayTimestamp - j * 30 * 60 * 1000,
        duration: Math.floor(10 + Math.random() * 50),
        isAlert: posture.status === 'poor'
      })
    }
  }

  return data.sort((a, b) => b.timestamp - a.timestamp)
}

