/**
 * 姿态数据模型
 */

/**
 * 姿态数据结构
 * @typedef {Object} PostureData
 * @property {number} neckAngle - 颈部角度
 * @property {number} backAngle - 背部角度
 * @property {number} shoulderAngle - 肩部角度
 * @property {string} postureType - 姿态类型 (sitting/standing/lying)
 * @property {string} status - 姿态状态 (good/fair/poor)
 * @property {number} timestamp - 时间戳
 */

class PostureModel {
  /**
   * 创建姿态数据对象
   * @param {Object} data - 原始数据
   * @returns {PostureData} 姿态数据
   */
  static create(data) {
    return {
      neckAngle: data.neckAngle || 0,
      backAngle: data.backAngle || 0,
      shoulderAngle: data.shoulderAngle || 0,
      postureType: data.postureType || 'unknown',
      status: data.status || 'good',
      timestamp: data.timestamp || Date.now()
    }
  }

  /**
   * 验证姿态数据
   * @param {PostureData} data - 姿态数据
   * @returns {boolean} 是否有效
   */
  static validate(data) {
    if (!data) return false

    const validTypes = ['sitting', 'standing', 'lying', 'unknown']
    const validStatus = ['good', 'fair', 'poor']

    return (
      typeof data.neckAngle === 'number' &&
      typeof data.backAngle === 'number' &&
      validTypes.includes(data.postureType) &&
      validStatus.includes(data.status) &&
      typeof data.timestamp === 'number'
    )
  }

  /**
   * 计算姿态健康评分
   * @param {PostureData} data - 姿态数据
   * @returns {number} 健康评分 (0-100)
   */
  static calculateScore(data) {
    if (!this.validate(data)) return 0

    let score = 100

    // 颈部角度扣分
    if (data.neckAngle > 15) {
      score -= (data.neckAngle - 15) * 2
    }

    // 背部角度扣分
    if (data.backAngle > 20) {
      score -= (data.backAngle - 20) * 2
    }

    // 根据状态调整
    if (data.status === 'poor') {
      score -= 20
    } else if (data.status === 'fair') {
      score -= 10
    }

    return Math.max(0, Math.min(100, Math.round(score)))
  }

  /**
   * 获取姿态描述
   * @param {string} postureType - 姿态类型
   * @returns {string} 描述文本
   */
  static getPostureDescription(postureType) {
    const descriptions = {
      sitting: '坐姿',
      standing: '站姿',
      lying: '躺姿',
      unknown: '未知姿态'
    }
    return descriptions[postureType] || '未知'
  }

  /**
   * 获取状态描述
   * @param {string} status - 状态
   * @returns {string} 描述文本
   */
  static getStatusDescription(status) {
    const descriptions = {
      good: '良好',
      fair: '一般',
      poor: '不佳'
    }
    return descriptions[status] || '未知'
  }

  /**
   * 获取状态颜色
   * @param {string} status - 状态
   * @returns {string} 颜色代码
   */
  static getStatusColor(status) {
    const colors = {
      good: '#52c41a',
      fair: '#faad14',
      poor: '#ff4d4f'
    }
    return colors[status] || '#999999'
  }

  /**
   * 格式化角度显示
   * @param {number} angle - 角度值
   * @returns {string} 格式化后的角度
   */
  static formatAngle(angle) {
    return `${Math.round(angle)}°`
  }

  /**
   * 比较两个姿态数据
   * @param {PostureData} a - 姿态数据A
   * @param {PostureData} b - 姿态数据B
   * @returns {number} 差异值（越小越相似）
   */
  static compare(a, b) {
    if (!this.validate(a) || !this.validate(b)) return Infinity

    const neckDiff = Math.abs(a.neckAngle - b.neckAngle)
    const backDiff = Math.abs(a.backAngle - b.backAngle)

    return neckDiff + backDiff
  }

  /**
   * 计算平均姿态
   * @param {Array<PostureData>} dataArray - 姿态数据数组
   * @returns {PostureData} 平均姿态数据
   */
  static average(dataArray) {
    if (!dataArray || dataArray.length === 0) {
      return this.create({})
    }

    const validData = dataArray.filter(d => this.validate(d))
    if (validData.length === 0) {
      return this.create({})
    }

    const sum = validData.reduce((acc, data) => ({
      neckAngle: acc.neckAngle + data.neckAngle,
      backAngle: acc.backAngle + data.backAngle,
      shoulderAngle: acc.shoulderAngle + (data.shoulderAngle || 0)
    }), { neckAngle: 0, backAngle: 0, shoulderAngle: 0 })

    const count = validData.length

    return this.create({
      neckAngle: sum.neckAngle / count,
      backAngle: sum.backAngle / count,
      shoulderAngle: sum.shoulderAngle / count,
      postureType: validData[validData.length - 1].postureType,
      status: this.determineStatus(sum.neckAngle / count, sum.backAngle / count),
      timestamp: Date.now()
    })
  }

  /**
   * 根据角度判断状态
   */
  static determineStatus(neckAngle, backAngle) {
    if (neckAngle > 20 || backAngle > 30) return 'poor'
    if (neckAngle > 15 || backAngle > 20) return 'fair'
    return 'good'
  }
}

export default PostureModel

/**
 * 警报数据模型
 */

/**
 * 警报数据结构
 * @typedef {Object} AlertData
 * @property {string} id - 警报ID
 * @property {string} type - 警报类型
 * @property {string} message - 警报消息
 * @property {Object} data - 相关数据
 * @property {number} timestamp - 时间戳
 * @property {boolean} read - 是否已读
 */

class AlertModel {
  /**
   * 创建警报数据对象
   * @param {Object} data - 原始数据
   * @returns {AlertData} 警报数据
   */
  static create(data) {
    return {
      id: data.id || this.generateId(),
      type: data.type || 'unknown',
      message: data.message || '',
      data: data.data || {},
      timestamp: data.timestamp || Date.now(),
      read: data.read || false
    }
  }

  /**
   * 生成唯一ID
   * @returns {string} 唯一ID
   */
  static generateId() {
    return `alert_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
  }

  /**
   * 验证警报数据
   * @param {AlertData} data - 警报数据
   * @returns {boolean} 是否有效
   */
  static validate(data) {
    if (!data) return false

    const validTypes = ['bad_posture', 'idle', 'neck_low', 'back_curve']

    return (
      typeof data.id === 'string' &&
      validTypes.includes(data.type) &&
      typeof data.message === 'string' &&
      typeof data.timestamp === 'number'
    )
  }

  /**
   * 获取警报类型描述
   * @param {string} type - 警报类型
   * @returns {string} 描述文本
   */
  static getTypeDescription(type) {
    const descriptions = {
      bad_posture: '姿态不佳',
      idle: '久坐提醒',
      neck_low: '低头提醒',
      back_curve: '驼背提醒',
      unknown: '未知提醒'
    }
    return descriptions[type] || '未知'
  }

  /**
   * 获取警报图标
   * @param {string} type - 警报类型
   * @returns {string} 图标
   */
  static getTypeIcon(type) {
    const icons = {
      bad_posture: '⚠️',
      idle: '⏰',
      neck_low: '🔽',
      back_curve: '🔙',
      unknown: '❓'
    }
    return icons[type] || '❓'
  }

  /**
   * 获取警报颜色
   * @param {string} type - 警报类型
   * @returns {string} 颜色代码
   */
  static getTypeColor(type) {
    const colors = {
      bad_posture: '#ff4d4f',
      idle: '#faad14',
      neck_low: '#ff7a45',
      back_curve: '#ff4d4f',
      unknown: '#999999'
    }
    return colors[type] || '#999999'
  }

  /**
   * 格式化时间显示
   * @param {number} timestamp - 时间戳
   * @returns {string} 格式化后的时间
   */
  static formatTime(timestamp) {
    const date = new Date(timestamp)
    const hours = String(date.getHours()).padStart(2, '0')
    const minutes = String(date.getMinutes()).padStart(2, '0')
    return `${hours}:${minutes}`
  }

  /**
   * 获取相对时间
   * @param {number} timestamp - 时间戳
   * @returns {string} 相对时间描述
   */
  static getRelativeTime(timestamp) {
    const now = Date.now()
    const diff = now - timestamp

    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) return '刚刚'
    if (minutes < 60) return `${minutes}分钟前`
    if (hours < 24) return `${hours}小时前`
    if (days < 7) return `${days}天前`
    return this.formatTime(timestamp)
  }

  /**
   * 标记为已读
   * @param {AlertData} data - 警报数据
   * @returns {AlertData} 更新后的警报数据
   */
  static markAsRead(data) {
    return {
      ...data,
      read: true
    }
  }

  /**
   * 过滤未读警报
   * @param {Array<AlertData>} alerts - 警报数组
   * @returns {Array<AlertData>} 未读警报数组
   */
  static getUnread(alerts) {
    return alerts.filter(a => !a.read)
  }

  /**
   * 按时间排序（最新在前）
   * @param {Array<AlertData>} alerts - 警报数组
   * @returns {Array<AlertData>} 排序后的警报数组
   */
  static sortByTime(alerts) {
    return [...alerts].sort((a, b) => b.timestamp - a.timestamp)
  }

  /**
   * 按类型分组
   * @param {Array<AlertData>} alerts - 警报数组
   * @returns {Object} 分组后的警报对象
   */
  static groupByType(alerts) {
    return alerts.reduce((groups, alert) => {
      const type = alert.type
      if (!groups[type]) {
        groups[type] = []
      }
      groups[type].push(alert)
      return groups
    }, {})
  }

  /**
   * 获取今日警报
   * @param {Array<AlertData>} alerts - 警报数组
   * @returns {Array<AlertData>} 今日警报数组
   */
  static getTodayAlerts(alerts) {
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const todayTimestamp = today.getTime()

    return alerts.filter(a => a.timestamp >= todayTimestamp)
  }

  /**
   * 获取警报统计
   * @param {Array<AlertData>} alerts - 警报数组
   * @returns {Object} 统计数据
   */
  static getStats(alerts) {
    const todayAlerts = this.getTodayAlerts(alerts)
    const unread = this.getUnread(alerts)
    const grouped = this.groupByType(alerts)

    return {
      total: alerts.length,
      today: todayAlerts.length,
      unread: unread.length,
      byType: Object.keys(grouped).reduce((acc, type) => {
        acc[type] = grouped[type].length
        return acc
      }, {})
    }
  }
