/**
 * 数据同步服务
 * 负责应用间的数据共享和同步
 * 注意：实际使用时需要在应用内部导入系统模块
 */

// 数据键名定义
export const DATA_KEYS = {
  // 姿态识别数据
  POSTURE_LATEST: 'posture_latest',
  POSTURE_HISTORY: 'posture_history',
  POSTURE_SCORE: 'posture_score',
  POSTURE_ALERTS: 'posture_alerts',

  // 健康数据
  HEALTH_HEART_RATE: 'health_heart_rate',
  HEALTH_STEPS: 'health_steps',
  HEALTH_SLEEP: 'health_sleep',

  // 通用数据
  USER_SETTINGS: 'user_settings',
  DAILY_GOALS: 'daily_goals'
}

class DataSyncService {
  constructor() {
    this.listeners = new Map()
    this.storage = null
  }

  /**
   * 初始化存储服务
   * 需要在应用内部调用并传入 storage 模块
   * @param {Object} storageModule - 系统存储模块
   */
  init(storageModule) {
    this.storage = storageModule
  }

  /**
   * 保存数据
   * @param {string} key - 数据键名
   * @param {*} value - 数据值
   * @returns {Promise}
   */
  setData(key, value) {
    if (!this.storage) {
      console.error('[DataSync] 存储服务未初始化')
      return Promise.reject(new Error('存储服务未初始化'))
    }

    return new Promise((resolve, reject) => {
      this.storage.set({
        key,
        value: JSON.stringify(value),
        success: () => {
          this.notifyListeners(key, value)
          resolve()
        },
        fail: (data, code) => {
          console.error(`[DataSync] 设置数据失败: ${key}`, code)
          reject(new Error(`设置数据失败: ${code}`))
        }
      })
    })
  }

  /**
   * 获取数据
   * @param {string} key - 数据键名
   * @param {*} defaultValue - 默认值
   * @returns {Promise<*>}
   */
  getData(key, defaultValue = null) {
    if (!this.storage) {
      console.error('[DataSync] 存储服务未初始化')
      return Promise.resolve(defaultValue)
    }

    return new Promise((resolve) => {
      this.storage.get({
        key,
        success: (data) => {
          try {
            resolve(data ? JSON.parse(data) : defaultValue)
          } catch (e) {
            resolve(defaultValue)
          }
        },
        fail: (data, code) => {
          console.error(`[DataSync] 获取数据失败: ${key}`, code)
          resolve(defaultValue)
        }
      })
    })
  }

  /**
   * 删除数据
   * @param {string} key - 数据键名
   * @returns {Promise}
   */
  removeData(key) {
    if (!this.storage) {
      console.error('[DataSync] 存储服务未初始化')
      return Promise.reject(new Error('存储服务未初始化'))
    }

    return new Promise((resolve, reject) => {
      this.storage.delete({
        key,
        success: () => {
          this.notifyListeners(key, null)
          resolve()
        },
        fail: (data, code) => {
          console.error(`[DataSync] 删除数据失败: ${key}`, code)
          reject(new Error(`删除数据失败: ${code}`))
        }
      })
    })
  }

  /**
   * 订阅数据变化
   * @param {string} key - 数据键名
   * @param {Function} callback - 回调函数
   */
  subscribe(key, callback) {
    if (!this.listeners.has(key)) {
      this.listeners.set(key, [])
    }
    this.listeners.get(key).push(callback)
  }

  /**
   * 取消订阅
   * @param {string} key - 数据键名
   * @param {Function} callback - 回调函数
   */
  unsubscribe(key, callback) {
    if (this.listeners.has(key)) {
      const callbacks = this.listeners.get(key)
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  /**
   * 通知监听者
   * @param {string} key - 数据键名
   * @param {*} value - 数据值
   */
  notifyListeners(key, value) {
    if (this.listeners.has(key)) {
      this.listeners.get(key).forEach(callback => {
        try {
          callback(value)
        } catch (e) {
          console.error(`[DataSync] 通知监听者失败: ${key}`, e)
        }
      })
    }
  }

  /**
   * 保存姿态数据
   * @param {Object} postureData - 姿态数据
   */
  async savePostureData(postureData) {
    const data = {
      ...postureData,
      timestamp: Date.now()
    }
    await this.setData(DATA_KEYS.POSTURE_LATEST, data)

    // 添加到历史记录
    const history = await this.getData(DATA_KEYS.POSTURE_HISTORY, [])
    history.unshift(data)
    // 保留最近100条记录
    if (history.length > 100) {
      history.pop()
    }
    await this.setData(DATA_KEYS.POSTURE_HISTORY, history)
  }

  /**
   * 保存健康数据
   * @param {string} type - 数据类型 (heart_rate/steps/sleep)
   * @param {*} data - 健康数据
   */
  async saveHealthData(type, data) {
    const key = `health_${type}`
    await this.setData(key, {
      ...data,
      timestamp: Date.now()
    })
  }
}

export default new DataSyncService()

/**
 * 事件总线服务
 * 用于应用内和应用间的事件通信
 */

class EventBus {
  constructor() {
    this.subscribers = new Map()
  }

  /**
   * 订阅事件
   * @param {string} event - 事件名称
   * @param {Function} callback - 回调函数
   * @returns {Function} 取消订阅函数
   */
  subscribe(event, callback) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, [])
    }
    this.subscribers.get(event).push(callback)

    // 返回取消订阅函数
    return () => {
      this.unsubscribe(event, callback)
    }
  }

  /**
   * 取消订阅
   * @param {string} event - 事件名称
   * @param {Function} callback - 回调函数
   */
  unsubscribe(event, callback) {
    if (this.subscribers.has(event)) {
      const callbacks = this.subscribers.get(event)
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  /**
   * 发布事件
   * @param {string} event - 事件名称
   * @param {*} data - 事件数据
   */
  publish(event, data) {
    if (this.subscribers.has(event)) {
      this.subscribers.get(event).forEach(callback => {
        try {
          callback(data)
        } catch (e) {
          console.error(`[EventBus] 事件处理错误: ${event}`, e)
        }
      })
    }
  }

  /**
   * 清除所有订阅
   */
  clear() {
    this.subscribers.clear()
  }
}

// 预定义的事件类型
export const EVENTS = {
  // 姿态识别事件
  POSTURE_UPDATE: 'posture:update',
  POSTURE_ALERT: 'posture:alert',
  POSTURE_SCORE_UPDATE: 'posture:score:update',

  // 健康数据事件
  HEALTH_HEART_RATE_UPDATE: 'health:heart_rate:update',
  HEALTH_STEPS_UPDATE: 'health:steps:update',
  HEALTH_SLEEP_UPDATE: 'health:sleep:update',

  // 系统事件
  APP_CONNECTED: 'app:connected',
  APP_DISCONNECTED: 'app:disconnected',
  SENSOR_DATA: 'sensor:data'
}

export default new EventBus()

/**
 * 存储服务
 * 封装 OpenVela 存储 API，提供统一的存储接口
 * 注意：实际使用时需要在应用内部导入系统模块并初始化
 */

class StorageService {
  constructor() {
    this.storage = null
  }

  /**
   * 初始化存储服务
   * 需要在应用内部调用并传入 storage 模块
   * @param {Object} storageModule - 系统存储模块
   */
  init(storageModule) {
    this.storage = storageModule
  }

  /**
   * 保存字符串数据
   * @param {string} key - 键名
   * @param {string} value - 值
   * @returns {Promise}
   */
  setString(key, value) {
    if (!this.storage) {
      console.error('[Storage] 存储服务未初始化')
      return Promise.reject(new Error('存储服务未初始化'))
    }

    return new Promise((resolve, reject) => {
      this.storage.set({
        key,
        value,
        success: () => resolve(),
        fail: (data, code) => {
          console.error(`[Storage] 保存失败: ${key}`, code)
          reject(new Error(`保存失败: ${code}`))
        }
      })
    })
  }

  /**
   * 获取字符串数据
   * @param {string} key - 键名
   * @param {string} defaultValue - 默认值
   * @returns {Promise<string>}
   */
  getString(key, defaultValue = '') {
    if (!this.storage) {
      console.error('[Storage] 存储服务未初始化')
      return Promise.resolve(defaultValue)
    }

    return new Promise((resolve) => {
      this.storage.get({
        key,
        success: (data) => resolve(data || defaultValue),
        fail: () => resolve(defaultValue)
      })
    })
  }

  /**
   * 保存对象数据（自动 JSON 序列化）
   * @param {string} key - 键名
   * @param {Object} value - 对象值
   * @returns {Promise}
   */
  setObject(key, value) {
    return this.setString(key, JSON.stringify(value))
  }

  /**
   * 获取对象数据（自动 JSON 反序列化）
   * @param {string} key - 键名
   * @param {Object} defaultValue - 默认值
   * @returns {Promise<Object>}
   */
  async getObject(key, defaultValue = {}) {
    const data = await this.getString(key)
    try {
      return data ? JSON.parse(data) : defaultValue
    } catch (e) {
      return defaultValue
    }
  }

  /**
   * 删除数据
   * @param {string} key - 键名
   * @returns {Promise}
   */
  remove(key) {
    if (!this.storage) {
      console.error('[Storage] 存储服务未初始化')
      return Promise.reject(new Error('存储服务未初始化'))
    }

    return new Promise((resolve, reject) => {
      this.storage.delete({
        key,
        success: () => resolve(),
        fail: (data, code) => {
          console.error(`[Storage] 删除失败: ${key}`, code)
          reject(new Error(`删除失败: ${code}`))
        }
      })
    })
  }

  /**
   * 清除所有数据
   * @returns {Promise}
   */
  clear() {
    if (!this.storage) {
      console.error('[Storage] 存储服务未初始化')
      return Promise.reject(new Error('存储服务未初始化'))
    }

    return new Promise((resolve, reject) => {
      this.storage.clear({
        success: () => resolve(),
        fail: (data, code) => {
          console.error('[Storage] 清除失败', code)
          reject(new Error(`清除失败: ${code}`))
        }
      })
    })
  }
}

export default new StorageService()

/**
 * 传感器服务
 * 封装 OpenVela 传感器 API，提供统一的传感器数据采集接口
 * 注意：实际使用时需要在应用内部导入系统模块并初始化
 */

class SensorService {
  constructor() {
    this.sensor = null
    this.isAccelerometerActive = false
    this.isGyroscopeActive = false
    this.accelerometerCallback = null
    this.gyroscopeCallback = null
  }

  /**
   * 初始化传感器服务
   * 需要在应用内部调用并传入 sensor 模块
   * @param {Object} sensorModule - 系统传感器模块
   */
  init(sensorModule) {
    this.sensor = sensorModule
  }

  /**
   * 订阅加速度传感器
   * @param {Function} callback - 回调函数，接收 {x, y, z} 数据
   */
  subscribeAccelerometer(callback) {
    if (!this.sensor) {
      console.error('[Sensor] 传感器服务未初始化')
      return
    }

    if (this.isAccelerometerActive) {
      console.warn('[Sensor] 加速度传感器已激活')
      return
    }

    this.accelerometerCallback = callback

    this.sensor.subscribeAccelerometer({
      callback: (data) => {
        if (this.accelerometerCallback) {
          this.accelerometerCallback({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        }
      },
      fail: (data, code) => {
        console.error('[Sensor] 加速度传感器订阅失败', code)
      }
    })

    this.isAccelerometerActive = true
    console.log('[Sensor] 加速度传感器已订阅')
  }

  /**
   * 取消订阅加速度传感器
   */
  unsubscribeAccelerometer() {
    if (!this.sensor || !this.isAccelerometerActive) {
      return
    }

    this.sensor.unsubscribeAccelerometer({
      success: () => {
        this.isAccelerometerActive = false
        this.accelerometerCallback = null
        console.log('[Sensor] 加速度传感器已取消订阅')
      },
      fail: (data, code) => {
        console.error('[Sensor] 加速度传感器取消订阅失败', code)
      }
    })
  }

  /**
   * 订阅陀螺仪
   * @param {Function} callback - 回调函数，接收 {x, y, z} 数据
   */
  subscribeGyroscope(callback) {
    if (!this.sensor) {
      console.error('[Sensor] 传感器服务未初始化')
      return
    }

    if (this.isGyroscopeActive) {
      console.warn('[Sensor] 陀螺仪已激活')
      return
    }

    this.gyroscopeCallback = callback

    this.sensor.subscribeGyroscope({
      callback: (data) => {
        if (this.gyroscopeCallback) {
          this.gyroscopeCallback({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        }
      },
      fail: (data, code) => {
        console.error('[Sensor] 陀螺仪订阅失败', code)
      }
    })

    this.isGyroscopeActive = true
    console.log('[Sensor] 陀螺仪已订阅')
  }

  /**
   * 取消订阅陀螺仪
   */
  unsubscribeGyroscope() {
    if (!this.sensor || !this.isGyroscopeActive) {
      return
    }

    this.sensor.unsubscribeGyroscope({
      success: () => {
        this.isGyroscopeActive = false
        this.gyroscopeCallback = null
        console.log('[Sensor] 陀螺仪已取消订阅')
      },
      fail: (data, code) => {
        console.error('[Sensor] 陀螺仪取消订阅失败', code)
      }
    })
  }

  /**
   * 取消所有传感器订阅
   */
  unsubscribeAll() {
    this.unsubscribeAccelerometer()
    this.unsubscribeGyroscope()
  }

  /**
   * 获取传感器状态
   * @returns {Object} 传感器状态
   */
  getStatus() {
    return {
      accelerometer: this.isAccelerometerActive,
      gyroscope: this.isGyroscopeActive
    }
  }
}

export default new SensorService()

