input.content:
/**
 * 姿态识别助手 - 测试数据可视化脚本
 *
 * 本脚本用于在控制台中可视化测试数据变化，
 * 帮助开发者理解数据流动和状态变化。
 *
 * 使用方法：
 * 1. 在 AIoT IDE 的控制台中运行
 * 2. 或者在 Node.js 环境中运行
 */

// 模拟姿态数据
class PostureDataSimulator {
  constructor() {
    this.data = {
      neckAngle: 15,
      backAngle: 20,
      sittingTime: 0,
      postureType: '坐姿良好',
      score: 85,
      alertCount: 0
    }
    this.history = []
    this.isMonitoring = false
    this.timer = null
  }

  // 模拟良好姿态
  simulateGood() {
    this.data = {
      neckAngle: 8,
      backAngle: 12,
      sittingTime: 30,
      postureType: '坐姿良好',
      score: 95,
      alertCount: 0
    }
    this.recordHistory('良好')
    this.displayData('✅ 良好姿态')
  }

  // 模拟一般姿态
  simulateFair() {
    this.data = {
      neckAngle: 18,
      backAngle: 22,
      sittingTime: 45,
      postureType: '坐姿一般',
      score: 70,
      alertCount: 3
    }
    this.recordHistory('一般')
    this.displayData('⚠️ 一般姿态')
  }

  // 模拟不佳姿态
  simulatePoor() {
    this.data = {
      neckAngle: 35,
      backAngle: 40,
      sittingTime: 60,
      postureType: '坐姿不佳',
      score: 40,
      alertCount: 8
    }
    this.recordHistory('不佳')
    this.displayData('❌ 不佳姿态')
  }

  // 生成随机数据
  generateRandomData() {
    const neckAngle = 10 + Math.floor(Math.random() * 30)
    const backAngle = 15 + Math.floor(Math.random() * 35)
    const sittingTime = 30 + Math.floor(Math.random() * 30)

    let postureType, score, alertCount

    if (neckAngle > 25 || backAngle > 30) {
      postureType = '坐姿不佳'
      score = 40 + Math.floor(Math.random() * 20)
      alertCount = 6 + Math.floor(Math.random() * 4)
    } else if (neckAngle > 15 || backAngle > 20) {
      postureType = '坐姿一般'
      score = 60 + Math.floor(Math.random() * 20)
      alertCount = 2 + Math.floor(Math.random() * 4)
    } else {
      postureType = '坐姿良好'
      score = 80 + Math.floor(Math.random() * 15)
      alertCount = Math.floor(Math.random() * 2)
    }

    this.data = { neckAngle, backAngle, sittingTime, postureType, score, alertCount }
    this.displayData('🔄 随机数据')
  }

  // 记录历史
  recordHistory(type) {
    const time = new Date().toLocaleTimeString()
    this.history.push({
      time,
      type,
      ...this.data
    })

    // 只保留最近 10 条记录
    if (this.history.length > 10) {
      this.history.shift()
    }
  }

  // 显示数据
  displayData(label) {
    console.log('\n' + '='.repeat(60))
    console.log(`${label} - ${new Date().toLocaleTimeString()}`)
    console.log('='.repeat(60))
    console.log(`  颈部角度: ${this.data.neckAngle}° ${this.getBar(this.data.neckAngle, 50)}`)
    console.log(`  背部角度: ${this.data.backAngle}° ${this.getBar(this.data.backAngle, 50)}`)
    console.log(`  坐姿时长: ${this.data.sittingTime} 分钟`)
    console.log(`  姿态类型: ${this.data.postureType}`)
    console.log(`  健康评分: ${this.data.score} ${this.getScoreBar(this.data.score)}`)
    console.log(`  提醒次数: ${this.data.alertCount}`)
    console.log('='.repeat(60))
  }

  // 生成进度条
  getBar(value, max) {
    const length = 20
    const filled = Math.round((value / max) * length)
    const empty = length - filled
    return '[' + '█'.repeat(filled) + '░'.repeat(empty) + ']'
  }

  // 生成评分进度条
  getScoreBar(score) {
    const length = 20
    const filled = Math.round((score / 100) * length)
    const empty = length - filled
    return '[' + '█'.repeat(filled) + '░'.repeat(empty) + ']'
  }

  // 显示历史记录
  displayHistory() {
    console.log('\n' + '='.repeat(60))
    console.log('📊 历史记录')
    console.log('='.repeat(60))

    if (this.history.length === 0) {
      console.log('  暂无记录')
    } else {
      this.history.forEach((record, index) => {
        console.log(`  ${index + 1}. ${record.time} - ${record.type} (评分: ${record.score})`)
      })
    }

    console.log('='.repeat(60))
  }

  // 生成统计报告
  generateReport() {
    if (this.history.length === 0) {
      console.log('\n  暂无历史数据，无法生成报告')
      return
    }

    const scores = this.history.map(r => r.score)
    const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
    const maxScore = Math.max(...scores)
    const minScore = Math.min(...scores)

    const goodCount = this.history.filter(r => r.type === '良好').length
    const fairCount = this.history.filter(r => r.type === '一般').length
    const poorCount = this.history.filter(r => r.type === '不佳').length

    console.log('\n' + '='.repeat(60))
    console.log('📈 统计报告')
    console.log('='.repeat(60))
    console.log(`  总记录数: ${this.history.length}`)
    console.log(`  平均评分: ${avgScore}`)
    console.log(`  最高评分: ${maxScore}`)
    console.log(`  最低评分: ${minScore}`)
    console.log(`  良好次数: ${goodCount} (${Math.round(goodCount / this.history.length * 100)}%)`)
    console.log(`  一般次数: ${fairCount} (${Math.round(fairCount / this.history.length * 100)}%)`)
    console.log(`  不佳次数: ${poorCount} (${Math.round(poorCount / this.history.length * 100)}%)`)
    console.log('='.repeat(60))
  }

  // 开始自动监测
  startMonitoring() {
    if (this.isMonitoring) {
      console.log('\n  ⚠️ 监测已在运行中')
      return
    }

    this.isMonitoring = true
    console.log('\n  🚀 开始自动监测（每 2 秒更新一次）')

    this.timer = setInterval(() => {
      this.generateRandomData()
      this.recordHistory('自动')
    }, 2000)
  }

  // 停止自动监测
  stopMonitoring() {
    if (!this.isMonitoring) {
      console.log('\n  ⚠️ 监测未在运行')
      return
    }

    this.isMonitoring = false
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
    console.log('\n  🛑 停止自动监测')
  }
}

// 创建模拟器实例
const simulator = new PostureDataSimulator()

// 显示帮助信息
function showHelp() {
  console.log('\n' + '='.repeat(60))
  console.log('🎯 姿态识别助手 - 测试数据可视化')
  console.log('='.repeat(60))
  console.log('  可用命令：')
  console.log('  ─────────────────────────────────────')
  console.log('  simulator.simulateGood()   - 模拟良好姿态')
  console.log('  simulator.simulateFair()   - 模拟一般姿态')
  console.log('  simulator.simulatePoor()   - 模拟不佳姿态')
  console.log('  simulator.generateRandomData() - 生成随机数据')
  console.log('  simulator.startMonitoring()    - 开始自动监测')
  console.log('  simulator.stopMonitoring()     - 停止自动监测')
  console.log('  simulator.displayHistory()     - 显示历史记录')
  console.log('  simulator.generateReport()     - 生成统计报告')
  console.log('  showHelp()                     - 显示此帮助')
  console.log('  ─────────────────────────────────────')
  console.log('  提示：在 AIoT IDE 控制台中输入命令')
  console.log('='.repeat(60))
}

// 导出模块（用于 Node.js 环境）
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { simulator, showHelp }
}

// 显示帮助
showHelp()

