/**
 * 姿态识别助手 - 模拟器内测试脚本
 *
 * 本脚本用于在模拟器控制台中测试数据变化效果
 * 可以直接在 AIoT IDE 的控制台中执行
 */

// 测试数据
const testData = {
  good: {
    neckAngle: 8,
    backAngle: 12,
    sittingTime: 30,
    postureType: '坐姿良好',
    score: 95,
    alertMessage: '模拟数据：姿势正确'
  },
  fair: {
    neckAngle: 18,
    backAngle: 22,
    sittingTime: 45,
    postureType: '坐姿一般',
    score: 70,
    alertMessage: '模拟数据：需要改善'
  },
  poor: {
    neckAngle: 35,
    backAngle: 40,
    sittingTime: 60,
    postureType: '坐姿不佳',
    score: 40,
    alertMessage: '模拟数据：坐姿严重不佳'
  }
}

// 模拟数据更新
function simulateDataUpdate(type) {
  const data = testData[type]
  if (!data) {
    console.log('无效的数据类型:', type)
    return
  }

  console.log('\n========================================')
  console.log(`模拟数据更新: ${type}`)
  console.log('========================================')
  console.log(`颈部角度: ${data.neckAngle}°`)
  console.log(`背部角度: ${data.backAngle}°`)
  console.log(`坐姿时长: ${data.sittingTime} 分钟`)
  console.log(`姿态类型: ${data.postureType}`)
  console.log(`健康评分: ${data.score}`)
  console.log(`提醒消息: ${data.alertMessage}`)
  console.log('========================================\n')
}

// 测试函数
function testGood() {
  simulateDataUpdate('good')
}

function testFair() {
  simulateDataUpdate('fair')
}

function testPoor() {
  simulateDataUpdate('poor')
}

// 显示帮助
function showTestHelp() {
  console.log('\n========================================')
  console.log('姿态识别助手 - 模拟器测试脚本')
  console.log('========================================')
  console.log('使用方法:')
  console.log('  testGood()  - 测试良好数据')
  console.log('  testFair()  - 测试一般数据')
  console.log('  testPoor()  - 测试不佳数据')
  console.log('  showTestHelp() - 显示此帮助')
  console.log('========================================\n')
}

// 显示帮助
showTestHelp()
